// ExTauri LiveView Hook — Bridge between Phoenix LiveView and Tauri APIs
// Generated by ExTauri. See ExTauri.Hook for documentation.
//
// Uses the global Tauri API (window.__TAURI__) rather than importing Tauri's
// npm packages, so no JavaScript dependencies are required: a stock Phoenix
// esbuild setup bundles this file as-is. The global API is populated by Tauri
// when `app.withGlobalTauri` is true in tauri.conf.json (set by
// mix ex_tauri.install), and each Rust-side plugin registers its own
// namespace on it.

function isTauri() {
  return window.__TAURI__ !== undefined;
}

// Resolves a namespace of the global Tauri API (e.g. "dialog", "fs", "window").
// Fails with an actionable error when the plugin isn't installed on the Rust side.
function tauriApi(namespace) {
  const api = window.__TAURI__ && window.__TAURI__[namespace];
  if (!api) {
    throw new Error(
      `Tauri API "${namespace}" is not available. ` +
        `Install the matching plugin with: mix ex_tauri.add — ` +
        `and make sure "withGlobalTauri" is true in src-tauri/tauri.conf.json`
    );
  }
  return api;
}

// Allowlist of valid commands to prevent arbitrary command injection
const ALLOWED_COMMANDS = new Set([
  "notification", "clipboard_write", "clipboard_read",
  "dialog_open", "dialog_save", "dialog_message",
  "os_info", "app_info", "fs_read", "fs_write", "fs_exists",
  "fs_readdir", "fs_remove", "fs_mkdir",
  "shell_open", "shell_exec", "invoke",
  "window", "window_open", "window_close",
  "event_listen", "event_unlisten", "event_emit",
  "shortcut_register", "shortcut_unregister", "shortcut_is_registered",
  "autostart_enable", "autostart_disable", "autostart_status",
  "process_exit", "process_relaunch",
  "updater_check", "updater_install"
]);

async function execWindowAction(payload) {
  const { getCurrentWindow } = tauriApi("window");
  const win = getCurrentWindow();

  switch (payload.action) {
    case "minimize":
      await win.minimize();
      return { status: "ok" };

    case "maximize":
      await win.maximize();
      return { status: "ok" };

    case "unmaximize":
      await win.unmaximize();
      return { status: "ok" };

    case "toggle_maximize":
      await win.toggleMaximize();
      return { status: "ok" };

    case "set_fullscreen":
      await win.setFullscreen(!!payload.fullscreen);
      return { status: "ok" };

    case "set_title":
      await win.setTitle(payload.title);
      return { status: "ok" };

    case "set_size": {
      const { LogicalSize } = tauriApi("dpi");
      await win.setSize(new LogicalSize(payload.width, payload.height));
      return { status: "ok" };
    }

    case "center":
      await win.center();
      return { status: "ok" };

    case "set_focus":
      await win.setFocus();
      return { status: "ok" };

    case "hide":
      await win.hide();
      return { status: "ok" };

    case "show":
      await win.show();
      return { status: "ok" };

    case "set_always_on_top":
      await win.setAlwaysOnTop(!!payload.value);
      return { status: "ok" };

    case "set_resizable":
      await win.setResizable(!!payload.value);
      return { status: "ok" };

    // Lets a `phx-click` element act as a drag handle for custom titlebars.
    case "start_dragging":
      await win.startDragging();
      return { status: "ok" };

    case "info": {
      const [title, isMaximized, isMinimized, isFullscreen, isFocused, scaleFactor] =
        await Promise.all([
          win.title(),
          win.isMaximized(),
          win.isMinimized(),
          win.isFullscreen(),
          win.isFocused(),
          win.scaleFactor(),
        ]);
      return {
        title,
        is_maximized: isMaximized,
        is_minimized: isMinimized,
        is_fullscreen: isFullscreen,
        is_focused: isFocused,
        scale_factor: scaleFactor,
      };
    }

    default:
      throw new Error(`Unknown window action: ${payload.action}`);
  }
}

async function execCommand(hook, command, payload) {
  if (!isTauri()) {
    throw new Error("Not running in Tauri — commands are only available in the desktop app");
  }

  if (!ALLOWED_COMMANDS.has(command)) {
    throw new Error(`Blocked unknown Tauri command: ${command}`);
  }

  switch (command) {
    case "notification": {
      const { sendNotification, isPermissionGranted, requestPermission } =
        tauriApi("notification");
      let permitted = await isPermissionGranted();
      if (!permitted) {
        const permission = await requestPermission();
        permitted = permission === "granted";
      }
      if (permitted) {
        sendNotification(payload);
        return { status: "sent" };
      }
      return { status: "denied" };
    }

    case "clipboard_write": {
      const { writeText } = tauriApi("clipboardManager");
      await writeText(payload.text);
      return { status: "ok" };
    }

    case "clipboard_read": {
      const { readText } = tauriApi("clipboardManager");
      const text = await readText();
      return { text };
    }

    case "dialog_open": {
      const { open } = tauriApi("dialog");
      const result = await open(payload);
      return { path: result };
    }

    case "dialog_save": {
      const { save } = tauriApi("dialog");
      const result = await save(payload);
      return { path: result };
    }

    case "dialog_message": {
      const { message, ask, confirm } = tauriApi("dialog");
      if (payload.type === "ask") {
        const result = await ask(payload.message, payload);
        return { result };
      } else if (payload.type === "confirm") {
        const result = await confirm(payload.message, payload);
        return { result };
      } else {
        await message(payload.message, payload);
        return { status: "ok" };
      }
    }

    case "os_info": {
      const os = tauriApi("os");
      return {
        platform: os.platform(),
        arch: os.arch(),
        version: os.version(),
        os_type: os.type(),
        locale: await os.locale(),
      };
    }

    case "app_info": {
      const app = tauriApi("app");
      const [name, version, tauriVersion] = await Promise.all([
        app.getName(),
        app.getVersion(),
        app.getTauriVersion(),
      ]);
      return { name, version, tauri_version: tauriVersion };
    }

    case "fs_read": {
      const { readTextFile } = tauriApi("fs");
      const opts = {};
      if (payload.baseDir) opts.baseDir = payload.baseDir;
      const contents = await readTextFile(payload.path, opts);
      return { contents };
    }

    case "fs_write": {
      const { writeTextFile } = tauriApi("fs");
      const opts = {};
      if (payload.baseDir) opts.baseDir = payload.baseDir;
      if (payload.append) opts.append = true;
      await writeTextFile(payload.path, payload.contents, opts);
      return { status: "ok" };
    }

    case "fs_exists": {
      const { exists } = tauriApi("fs");
      const opts = {};
      if (payload.baseDir) opts.baseDir = payload.baseDir;
      const result = await exists(payload.path, opts);
      return { exists: result };
    }

    case "fs_readdir": {
      const { readDir } = tauriApi("fs");
      const opts = {};
      if (payload.baseDir) opts.baseDir = payload.baseDir;
      const entries = await readDir(payload.path, opts);
      return { entries };
    }

    case "fs_remove": {
      const { remove } = tauriApi("fs");
      const opts = {};
      if (payload.baseDir) opts.baseDir = payload.baseDir;
      await remove(payload.path, opts);
      return { status: "ok" };
    }

    case "fs_mkdir": {
      const { mkdir } = tauriApi("fs");
      const opts = { recursive: payload.recursive !== false };
      if (payload.baseDir) opts.baseDir = payload.baseDir;
      await mkdir(payload.path, opts);
      return { status: "ok" };
    }

    case "shell_open": {
      const { open } = tauriApi("shell");
      await open(payload.url);
      return { status: "ok" };
    }

    case "shell_exec": {
      const { Command } = tauriApi("shell");
      const cmd = Command.create(payload.program, payload.args || []);
      const output = await cmd.execute();
      return { stdout: output.stdout, stderr: output.stderr, code: output.code };
    }

    case "invoke": {
      const { invoke } = tauriApi("core");
      const result = await invoke(payload.cmd, payload.args || {});
      return { result };
    }

    case "window":
      return execWindowAction(payload);

    case "window_open": {
      const { WebviewWindow } = tauriApi("webviewWindow");
      // Relative paths resolve against the Phoenix app's origin so callers can
      // pass LiveView routes like "/settings".
      const url = new URL(payload.url || "/", window.location.origin).toString();
      const options = { url };
      if (payload.title) options.title = payload.title;
      if (payload.width && payload.height) {
        options.width = payload.width;
        options.height = payload.height;
      }
      if (payload.resizable !== undefined) options.resizable = !!payload.resizable;

      const win = new WebviewWindow(payload.label, options);
      await new Promise((resolve, reject) => {
        win.once("tauri://created", resolve);
        win.once("tauri://error", (e) =>
          reject(new Error(`Failed to open window: ${JSON.stringify(e.payload || e)}`))
        );
      });
      return { status: "ok", label: payload.label };
    }

    case "window_close": {
      const { WebviewWindow } = tauriApi("webviewWindow");
      const win = await WebviewWindow.getByLabel(payload.label);
      if (!win) {
        throw new Error(`No window with label: ${payload.label}`);
      }
      await win.close();
      return { status: "ok", label: payload.label };
    }

    case "event_listen": {
      const { listen } = tauriApi("event");
      const name = payload.event;
      if (hook._eventUnlisteners[name]) {
        return { status: "already_listening", event: name };
      }
      const unlisten = await listen(name, (event) => {
        if (hook._destroyed) return;
        hook.pushEvent("tauri_event", { event: name, payload: event.payload });
      });
      // A second listen for the same name may have raced us; keep the first.
      if (hook._eventUnlisteners[name]) {
        unlisten();
        return { status: "already_listening", event: name };
      }
      hook._eventUnlisteners[name] = unlisten;
      return { status: "listening", event: name };
    }

    case "event_unlisten": {
      const name = payload.event;
      const unlisten = hook._eventUnlisteners[name];
      if (unlisten) {
        unlisten();
        delete hook._eventUnlisteners[name];
      }
      return { status: "ok", event: name };
    }

    case "event_emit": {
      const { emit } = tauriApi("event");
      await emit(payload.event, payload.payload);
      return { status: "ok" };
    }

    case "shortcut_register": {
      const { register } = tauriApi("globalShortcut");
      const shortcut = payload.shortcut;
      await register(shortcut, (event) => {
        if (hook._destroyed) return;
        hook.pushEvent("tauri_event", {
          event: "global_shortcut",
          shortcut: event.shortcut,
          state: event.state,
        });
      });
      return { status: "ok", shortcut };
    }

    case "shortcut_unregister": {
      const { unregister } = tauriApi("globalShortcut");
      await unregister(payload.shortcut);
      return { status: "ok", shortcut: payload.shortcut };
    }

    case "shortcut_is_registered": {
      const { isRegistered } = tauriApi("globalShortcut");
      const registered = await isRegistered(payload.shortcut);
      return { registered, shortcut: payload.shortcut };
    }

    case "autostart_enable": {
      const { enable } = tauriApi("autostart");
      await enable();
      return { status: "ok" };
    }

    case "autostart_disable": {
      const { disable } = tauriApi("autostart");
      await disable();
      return { status: "ok" };
    }

    case "autostart_status": {
      const { isEnabled } = tauriApi("autostart");
      const enabled = await isEnabled();
      return { enabled };
    }

    case "process_exit": {
      const { exit } = tauriApi("process");
      await exit(payload.code || 0);
      return { status: "ok" };
    }

    case "process_relaunch": {
      const { relaunch } = tauriApi("process");
      await relaunch();
      return { status: "ok" };
    }

    case "updater_check": {
      const { check } = tauriApi("updater");
      const update = await check();
      if (update) {
        // Kept so a follow-up updater_install can download this exact update.
        hook._pendingUpdate = update;
        return {
          available: true,
          version: update.version,
          notes: update.body || null,
          date: update.date || null,
        };
      }
      hook._pendingUpdate = null;
      return { available: false };
    }

    case "updater_install": {
      const update = hook._pendingUpdate;
      if (!update) {
        throw new Error("No pending update — run updater_check first");
      }
      await update.downloadAndInstall();
      hook._pendingUpdate = null;
      return { status: "installed" };
    }

    default:
      throw new Error(`Unknown Tauri command: ${command}`);
  }
}

export const TauriHook = {
  mounted() {
    this._eventUnlisteners = {};
    this._pendingUpdate = null;
    this._setupCommandHandler();
  },

  // Re-attach the event handler when LiveView reconnects after a disconnect.
  // Without this, commands pushed after reconnection would be silently dropped.
  reconnected() {
    this._setupCommandHandler();
  },

  // Clean up any in-flight state when the hook element is removed from the DOM.
  destroyed() {
    this._destroyed = true;
    for (const name of Object.keys(this._eventUnlisteners || {})) {
      this._eventUnlisteners[name]();
    }
    this._eventUnlisteners = {};
  },

  _setupCommandHandler() {
    this._destroyed = false;

    // handleEvent callbacks persist across reconnects, so re-registering
    // without removing the old one would run every command twice. Drop the
    // previous handler before attaching a fresh one.
    if (this._commandHandlerRef != null) {
      this.removeHandleEvent(this._commandHandlerRef);
    }

    this._commandHandlerRef = this.handleEvent("tauri_command", async ({ ref, command, payload }) => {
      // Guard against responses being pushed after the hook was destroyed
      // (e.g., a slow dialog resolved after navigation).
      if (this._destroyed) return;

      try {
        const result = await execCommand(this, command, payload);
        if (!this._destroyed) {
          this.pushEvent("tauri_response", { ref, command, ...result });
        }
      } catch (error) {
        if (!this._destroyed) {
          this.pushEvent("tauri_error", {
            ref,
            command,
            error: error.message || String(error),
          });
        }
      }
    });
  },
};
